package ca.team.originkickoff;

import android.content.Intent;
import android.os.Bundle;
import android.os.SystemClock;
import android.util.Log;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.fragment.app.Fragment;
import androidx.viewpager2.adapter.FragmentStateAdapter;
import androidx.viewpager2.widget.ViewPager2;

import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.android.material.tabs.TabLayout;
import com.google.android.material.tabs.TabLayoutMediator;
import com.google.firebase.firestore.FirebaseFirestore;

import androidx.appcompat.widget.Toolbar;

import ca.team.originkickoff.util.DeviceUtils;

public class MyEventsActivity extends AppCompatActivity {
    private static final String TAG = "MyEventsActivity";
    private TabLayout tabLayout;
    private ViewPager2 viewPager;
    private boolean isOrganizer = false;
    private FirebaseFirestore db;

    // Debounce for bottom-nav taps
    private long lastNavTapAtMs = 0L;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        setContentView(R.layout.activity_my_events);

        Toolbar toolbar = findViewById(R.id.toolbar);
        if (toolbar != null) {
            setSupportActionBar(toolbar);
        }

        if (getSupportActionBar() != null) {
            getSupportActionBar().setDisplayHomeAsUpEnabled(true);
            getSupportActionBar().setTitle("My Events");
        }

        db = FirebaseFirestore.getInstance();
        tabLayout = findViewById(R.id.tabLayout);
        viewPager = findViewById(R.id.viewPager);

        // Check if user is an organizer first, then setup tabs
        checkIfUserIsOrganizer();

        // Setup bottom navigation include
        setupBottomNav();
    }

    private void checkIfUserIsOrganizer() {
        String deviceId = DeviceUtils.getDeviceId(this);
        if (deviceId == null) {
            Log.w(TAG, "Device ID is null, defaulting to non-organizer");
            setupTabs(false);
            return;
        }

        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(queryDocumentSnapshots -> {
                    if (!queryDocumentSnapshots.isEmpty()) {
                        Boolean isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organizer");
                        isOrganizer = isOrganizerField != null && isOrganizerField;
                        Log.d(TAG, "User is organizer: " + isOrganizer);
                    } else {
                        Log.w(TAG, "No user found for device_id");
                        isOrganizer = false;
                    }
                    setupTabs(isOrganizer);
                })
                .addOnFailureListener(e -> {
                    Log.e(TAG, "Error checking organizer status", e);
                    isOrganizer = false;
                    setupTabs(false);
                });
    }

    private void setupTabs(boolean showOrganizerTab) {
        // Create adapter with dynamic tab count
        viewPager.setAdapter(new FragmentStateAdapter(this) {
            @NonNull
            @Override
            public Fragment createFragment(int position) {
                if (!showOrganizerTab) {
                    // Only show Events Joined
                    return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                } else {
                    // Show both tabs
                    if (position == 0) {
                        return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                    } else {
                        return new ca.team.originkickoff.ui.fragments.EventsOrganizedFragment();
                    }
                }
            }

            @Override
            public int getItemCount() {
                return showOrganizerTab ? 2 : 1;
            }
        });

        // Setup tab names
        new TabLayoutMediator(tabLayout, viewPager, (tab, position) -> {
            if (!showOrganizerTab) {
                // Only one tab
                tab.setText("Events Joined");
            } else {
                // Two tabs
                if (position == 0) {
                    tab.setText("Events Joined");
                } else {
                    tab.setText("Events Organized");
                }
            }
        }).attach();

        // Wire FAB: only visible for organizers on Events Organized tab (index 1)
        FloatingActionButton fab = findViewById(R.id.fabCreate);
        if (fab != null && showOrganizerTab) {
            fab.setOnClickListener(v -> startActivity(new Intent(MyEventsActivity.this, CreateEventActivity.class)));

            // initial visibility
            fab.setVisibility(viewPager.getCurrentItem() == 1 ? View.VISIBLE : View.GONE);

            // show/hide based on page
            viewPager.registerOnPageChangeCallback(new ViewPager2.OnPageChangeCallback() {
                @Override
                public void onPageSelected(int position) {
                    super.onPageSelected(position);
                    if (position == 1) fab.setVisibility(View.VISIBLE);
                    else fab.setVisibility(View.GONE);
                }
            });
        } else if (fab != null) {
            // Hide FAB completely for non-organizers
            fab.setVisibility(View.GONE);
        }
    }

    private void setupBottomNav() {
        LinearLayout navHome = findViewById(R.id.navHome);
        LinearLayout navEvents = findViewById(R.id.navEvents);
        LinearLayout navNotifications = findViewById(R.id.navNotifications);
        LinearLayout navProfile = findViewById(R.id.navProfile);

        if (navHome == null || navEvents == null || navNotifications == null || navProfile == null) return;

        // Highlight current tab (My Events)
        ImageView ivEvents = findViewById(R.id.ivEvents);
        TextView tvEvents = findViewById(R.id.tvEvents);
        if (ivEvents != null) ivEvents.setColorFilter(0xFF00D9C5, android.graphics.PorterDuff.Mode.SRC_IN);
        if (tvEvents != null) tvEvents.setTextColor(0xFF00D9C5);

        navHome.setOnClickListener(v -> navigateBottomTab(MainActivity.class));
        navEvents.setOnClickListener(v -> { /* already here */ });
        navNotifications.setOnClickListener(v -> navigateBottomTab(NotificationsActivity.class));
        navProfile.setOnClickListener(v -> navigateBottomTab(ProfileActivity.class));
    }

    // Helper to navigate between bottom-bar destinations smoothly with no transition animation
    private void navigateBottomTab(Class<?> targetActivity) {
        if (targetActivity == null) return;
        if (getClass().equals(targetActivity)) return; // already on this tab
        long now = SystemClock.elapsedRealtime();
        if (now - lastNavTapAtMs < 300) return; // debounce rapid taps
        lastNavTapAtMs = now;
        Intent intent = new Intent(this, targetActivity);
        intent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT | Intent.FLAG_ACTIVITY_NO_ANIMATION);
        startActivity(intent);
        overridePendingTransition(0, 0);
    }

    @Override
    public boolean onSupportNavigateUp() {
        finish();
        return true;
    }
}

package ca.team.originkickoff;

import android.content.Intent;
import android.os.Bundle;
import android.os.SystemClock;
import android.util.Log;
import android.view.View;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.TextView;

import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.fragment.app.Fragment;
import androidx.viewpager2.adapter.FragmentStateAdapter;
import androidx.viewpager2.widget.ViewPager2;

import com.google.android.material.floatingactionbutton.FloatingActionButton;
import com.google.android.material.tabs.TabLayout;
import com.google.android.material.tabs.TabLayoutMediator;
import com.google.firebase.firestore.FirebaseFirestore;

import androidx.appcompat.widget.Toolbar;

import ca.team.originkickoff.util.DeviceUtils;

public class MyEventsActivity extends AppCompatActivity {
    private static final String TAG = "MyEventsActivity";
    private TabLayout tabLayout;
    private ViewPager2 viewPager;
    private boolean isOrganizer = false;
    private FirebaseFirestore db;

    // Debounce for bottom-nav taps
    private long lastNavTapAtMs = 0L;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);

        setContentView(R.layout.activity_my_events);

        Toolbar toolbar = findViewById(R.id.toolbar);
        if (toolbar != null) {
            setSupportActionBar(toolbar);
        }

        if (getSupportActionBar() != null) {
            getSupportActionBar().setDisplayHomeAsUpEnabled(true);
            getSupportActionBar().setTitle("My Events");
        }

        db = FirebaseFirestore.getInstance();
        tabLayout = findViewById(R.id.tabLayout);
        viewPager = findViewById(R.id.viewPager);

        // Check if user is an organizer first, then setup tabs
        checkIfUserIsOrganizer();

        // Setup bottom navigation include
        setupBottomNav();
    }

    private void checkIfUserIsOrganizer() {
        String deviceId = DeviceUtils.getDeviceId(this);
        if (deviceId == null) {
            Log.w(TAG, "Device ID is null, defaulting to non-organizer");
            setupTabs(false);
            return;
        }

        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnSuccessListener(queryDocumentSnapshots -> {
                    if (!queryDocumentSnapshots.isEmpty()) {
                        Boolean isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organizer");
                        if (isOrganizerField == null) isOrganizerField = queryDocumentSnapshots.getDocuments().get(0).getBoolean("is_organiser");
                        if (isOrganizerField == null) {
                            Object camel = queryDocumentSnapshots.getDocuments().get(0).get("isOrganizer");
                            if (camel instanceof Boolean) isOrganizerField = (Boolean) camel;
                        }
                        isOrganizer = isOrganizerField != null && isOrganizerField;
                        Log.d(TAG, "User explicit organizer flag: " + isOrganizer);

                        if (!isOrganizer) {
                            // Fallback inference: does user have any events with organizerId == their document ID or deviceId?
                            String userDocId = queryDocumentSnapshots.getDocuments().get(0).getId();
                            java.util.List<String> possibleIds = new java.util.ArrayList<>();
                            possibleIds.add(userDocId);
                            if (!deviceId.equals(userDocId)) possibleIds.add(deviceId);
                            db.collection("events")
                                    .whereIn("organizerId", possibleIds)
                                    .limit(1)
                                    .get()
                                    .addOnSuccessListener(evSnap -> {
                                        if (!evSnap.isEmpty()) {
                                            Log.d(TAG, "Inferred organizer via existing events");
                                            isOrganizer = true;
                                        }
                                        setupTabs(isOrganizer);
                                    })
                                    .addOnFailureListener(e -> {
                                        Log.e(TAG, "Organizer inference failed", e);
                                        setupTabs(isOrganizer);
                                    });
                        } else {
                            setupTabs(true);
                        }
                    } else {
                        Log.w(TAG, "No user found for device_id");
                        isOrganizer = false;
                        setupTabs(false);
                    }
                })
                .addOnFailureListener(e -> {
                    Log.e(TAG, "Error checking organizer status", e);
                    isOrganizer = false;
                    setupTabs(false);
                });
    }

    private void setupTabs(boolean showOrganizerTab) {
        // Create adapter with dynamic tab count
        viewPager.setAdapter(new FragmentStateAdapter(this) {
            @NonNull
            @Override
            public Fragment createFragment(int position) {
                if (!showOrganizerTab) {
                    // Only show Events Joined
                    return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                } else {
                    // Show both tabs
                    if (position == 0) {
                        return new ca.team.originkickoff.ui.fragments.EventsJoinedFragment();
                    } else {
                        return new ca.team.originkickoff.ui.fragments.EventsOrganizedFragment();
                    }
                }
            }

            @Override
            public int getItemCount() {
                return showOrganizerTab ? 2 : 1;
            }
        });

        // Setup tab names
        new TabLayoutMediator(tabLayout, viewPager, (tab, position) -> {
            if (!showOrganizerTab) {
                // Only one tab
                tab.setText("Events Joined");
            } else {
                // Two tabs
                if (position == 0) {
                    tab.setText("Events Joined");
                } else {
                    tab.setText("Events Organized");
                }
            }
        }).attach();

        // Wire FAB: only visible for organizers on Events Organized tab (index 1)
        FloatingActionButton fab = findViewById(R.id.fabCreate);
        if (fab != null && showOrganizerTab) {
            fab.setOnClickListener(v -> startActivity(new Intent(MyEventsActivity.this, CreateEventActivity.class)));

            // initial visibility
            fab.setVisibility(viewPager.getCurrentItem() == 1 ? View.VISIBLE : View.GONE);

            // show/hide based on page
            viewPager.registerOnPageChangeCallback(new ViewPager2.OnPageChangeCallback() {
                @Override
                public void onPageSelected(int position) {
                    super.onPageSelected(position);
                    if (position == 1) fab.setVisibility(View.VISIBLE);
                    else fab.setVisibility(View.GONE);
                }
            });
        } else if (fab != null) {
            // Hide FAB completely for non-organizers
            fab.setVisibility(View.GONE);
        }
    }

    private void setupBottomNav() {
        LinearLayout navHome = findViewById(R.id.navHome);
        LinearLayout navEvents = findViewById(R.id.navEvents);
        LinearLayout navNotifications = findViewById(R.id.navNotifications);
        LinearLayout navProfile = findViewById(R.id.navProfile);

        if (navHome == null || navEvents == null || navNotifications == null || navProfile == null) return;

        // Highlight current tab (My Events)
        ImageView ivEvents = findViewById(R.id.ivEvents);
        TextView tvEvents = findViewById(R.id.tvEvents);
        if (ivEvents != null) ivEvents.setColorFilter(0xFF00D9C5, android.graphics.PorterDuff.Mode.SRC_IN);
        if (tvEvents != null) tvEvents.setTextColor(0xFF00D9C5);

        navHome.setOnClickListener(v -> navigateBottomTab(MainActivity.class));
        navEvents.setOnClickListener(v -> { /* already here */ });
        navNotifications.setOnClickListener(v -> navigateBottomTab(NotificationsActivity.class));
        navProfile.setOnClickListener(v -> navigateBottomTab(ProfileActivity.class));
    }

    // Helper to navigate between bottom-bar destinations smoothly with no transition animation
    private void navigateBottomTab(Class<?> targetActivity) {
        if (targetActivity == null) return;
        if (getClass().equals(targetActivity)) return; // already on this tab
        long now = SystemClock.elapsedRealtime();
        if (now - lastNavTapAtMs < 300) return; // debounce rapid taps
        lastNavTapAtMs = now;
        Intent intent = new Intent(this, targetActivity);
        intent.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT | Intent.FLAG_ACTIVITY_NO_ANIMATION);
        startActivity(intent);
        overridePendingTransition(0, 0);
    }

    @Override
    public boolean onSupportNavigateUp() {
        finish();
        return true;
    }
}

package ca.team.originkickoff.data.repository;

import androidx.lifecycle.LiveData;
import androidx.lifecycle.MutableLiveData;

import ca.team.originkickoff.models.User;
import com.google.firebase.firestore.FirebaseFirestore;

import java.util.Date;
import java.util.UUID;

public class UserRepository {

    private final FirebaseFirestore db = FirebaseFirestore.getInstance();

    public LiveData<User> findUserByDeviceId(String deviceId) {
        MutableLiveData<User> userLiveData = new MutableLiveData<>();
        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnCompleteListener(task -> {
                    if (task.isSuccessful() && !task.getResult().isEmpty()) {
                        User user = task.getResult().getDocuments().get(0).toObject(User.class);
                        if (user != null) {
                            // IMPORTANT: set id explicitly from document ID (not stored as field)
                            user.setId(task.getResult().getDocuments().get(0).getId());
                        }
                        userLiveData.postValue(user);
                    } else {
                        // User not found, create a new one
                        createNewUser(deviceId, userLiveData);
                    }
                });
        return userLiveData;
    }

    private void createNewUser(String deviceId, MutableLiveData<User> userLiveData) {
        User newUser = new User();
        // Use deviceId as both document id and internal id to align with rest of app and simplify lookups
        String userId = deviceId;
        newUser.setId(userId);
        newUser.setDeviceId(deviceId);
        newUser.setDisplayName(""); // Default empty display name
        newUser.setNotifMarketing(false);
        newUser.setNotifService(true);
        newUser.setOrganizer(false);
        newUser.setAdmin(false);
        newUser.setCreatedAt(new Date());
        newUser.setUpdatedAt(new Date());

        db.collection("users").document(userId).set(newUser)
                .addOnSuccessListener(aVoid -> userLiveData.postValue(newUser)) // On success, post the new user object
                .addOnFailureListener(e -> userLiveData.postValue(null)); // On failure, post null
    }
}

/**
 * Repository providing user lookup and creation operations backed by Firestore.
 * Ensures a user exists for a given device identifier (creating one if absent).
 */
package ca.team.originkickoff.data.repository;

import androidx.lifecycle.LiveData;
import androidx.lifecycle.MutableLiveData;

import ca.team.originkickoff.models.User;
import com.google.firebase.firestore.FirebaseFirestore;

import java.util.Date;

/**
 * Data access layer for User entities stored in the Firestore 'users' collection.
 */
public class UserRepository {

    private final FirebaseFirestore db = FirebaseFirestore.getInstance();

    /**
     * Retrieves a user by device id, creating a new persisted user document if none exists.
     * @param deviceId the device identifier used as a unique key
     * @return LiveData emitting the found or newly created User (or null on creation failure)
     */
    public LiveData<User> findUserByDeviceId(String deviceId) {
        MutableLiveData<User> userLiveData = new MutableLiveData<>();
        db.collection("users")
                .whereEqualTo("device_id", deviceId)
                .limit(1)
                .get()
                .addOnCompleteListener(task -> {
                    if (task.isSuccessful() && !task.getResult().isEmpty()) {
                        User user = task.getResult().getDocuments().get(0).toObject(User.class);
                        if (user != null) {
                            user.setId(task.getResult().getDocuments().get(0).getId());
                        }
                        userLiveData.postValue(user);
                    } else {
                        createNewUser(deviceId, userLiveData);
                    }
                });
        return userLiveData;
    }

    /**
     * Creates and persists a new user document initialized with default settings.
     * @param deviceId device identifier used as both document id and internal id
     * @param userLiveData target LiveData to publish result (user or null on failure)
     */
    private void createNewUser(String deviceId, MutableLiveData<User> userLiveData) {
        User newUser = new User();
        String userId = deviceId;
        newUser.setId(userId);
        newUser.setDeviceId(deviceId);
        newUser.setDisplayName("");
        newUser.setNotifMarketing(false);
        newUser.setNotifService(true);
        newUser.setOrganizer(false);
        newUser.setAdmin(false);
        newUser.setCreatedAt(new Date());
        newUser.setUpdatedAt(new Date());

        db.collection("users").document(userId).set(newUser)
                .addOnSuccessListener(aVoid -> userLiveData.postValue(newUser))
                .addOnFailureListener(e -> userLiveData.postValue(null));
    }
}

package ca.team.originkickoff.models;

import java.io.Serializable;
import java.util.Date;

public class Event implements Serializable {
    private String id;
    private String name;
    private String description;
    private String organizerId;
    private String organizerName;
    private Date eventDate;
    private String location;
    private double locationLatitude;
    private double locationLongitude;
    private String locationPlaceId;
    private String category;
    private int capacity;
    private int waitlistCount;
    private int selectionSize; // number of users to be selected
    private boolean limitWaitlist; // enable/disable waitlist limit
    private int waitlistLimit; // max entrants on waitlist when limit enabled
    private Date registrationStartTime;
    private Date registrationEndTime;
    private String posterUrl;
    private String posterBase64;
    private boolean geolocationRequired;
    private double price;
    private long createdAt;
    private String qrCodeUrl;
    private String qrCodeBase64;
    private String lotteryCriteria;
    private String lotteryStatus; // "not_conducted", "conducted", etc.

    // Empty constructor for Firebase
    public Event() {
    }

    public Event(String id, String name, String description, String organizerId, String organizerName,
                 Date eventDate, String location, String category, int capacity, int waitlistCount,
                 Date registrationStartTime, Date registrationEndTime, String posterUrl, String posterBase64,
                 boolean geolocationRequired, double price, long createdAt, String qrCodeUrl, String lotteryCriteria) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.organizerId = organizerId;
        this.organizerName = organizerName;
        this.eventDate = eventDate;
        this.location = location;
        this.category = category;
        this.capacity = capacity;
        this.waitlistCount = waitlistCount;
        this.registrationStartTime = registrationStartTime;
        this.registrationEndTime = registrationEndTime;
        this.posterUrl = posterUrl;
        this.posterBase64 = posterBase64;
        this.geolocationRequired = geolocationRequired;
        this.price = price;
        this.createdAt = createdAt;
        this.qrCodeUrl = qrCodeUrl;
        this.lotteryCriteria = lotteryCriteria;
    }

    // Getters and Setters
    public String getId() { return id; }
    public void setId(String id) { this.id = id; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getDescription() { return description; }
    public void setDescription(String description) { this.description = description; }

    public String getOrganizerId() { return organizerId; }
    public void setOrganizerId(String organizerId) { this.organizerId = organizerId; }

    public String getOrganizerName() { return organizerName; }
    public void setOrganizerName(String organizerName) { this.organizerName = organizerName; }

    public Date getEventDate() { return eventDate; }
    public void setEventDate(Date eventDate) { this.eventDate = eventDate; }

    public String getLocation() { return location; }
    public void setLocation(String location) { this.location = location; }

    public double getLocationLatitude() { return locationLatitude; }
    public void setLocationLatitude(double locationLatitude) { this.locationLatitude = locationLatitude; }

    public double getLocationLongitude() { return locationLongitude; }
    public void setLocationLongitude(double locationLongitude) { this.locationLongitude = locationLongitude; }

    public String getLocationPlaceId() { return locationPlaceId; }
    public void setLocationPlaceId(String locationPlaceId) { this.locationPlaceId = locationPlaceId; }

    public String getCategory() { return category; }
    public void setCategory(String category) { this.category = category; }

    public int getCapacity() { return capacity; }
    public void setCapacity(int capacity) { this.capacity = capacity; }

    public int getWaitlistCount() { return waitlistCount; }
    public void setWaitlistCount(int waitlistCount) { this.waitlistCount = waitlistCount; }

    public int getSelectionSize() { return selectionSize; }
    public void setSelectionSize(int selectionSize) { this.selectionSize = selectionSize; }

    public boolean isLimitWaitlist() { return limitWaitlist; }
    public void setLimitWaitlist(boolean limitWaitlist) { this.limitWaitlist = limitWaitlist; }

    public int getWaitlistLimit() { return waitlistLimit; }
    public void setWaitlistLimit(int waitlistLimit) { this.waitlistLimit = waitlistLimit; }

    public Date getRegistrationStartTime() { return registrationStartTime; }
    public void setRegistrationStartTime(Date registrationStartTime) { this.registrationStartTime = registrationStartTime; }

    public Date getRegistrationEndTime() { return registrationEndTime; }
    public void setRegistrationEndTime(Date registrationEndTime) { this.registrationEndTime = registrationEndTime; }

    public String getPosterUrl() { return posterUrl; }
    public void setPosterUrl(String posterUrl) { this.posterUrl = posterUrl; }

    public String getPosterBase64() { return posterBase64; }
    public void setPosterBase64(String posterBase64) { this.posterBase64 = posterBase64; }

    public boolean isGeolocationRequired() { return geolocationRequired; }
    public void setGeolocationRequired(boolean geolocationRequired) { this.geolocationRequired = geolocationRequired; }

    public double getPrice() { return price; }
    public void setPrice(double price) { this.price = price; }

    public long getCreatedAt() { return createdAt; }
    public void setCreatedAt(long createdAt) { this.createdAt = createdAt; }

    public String getQrCodeUrl() { return qrCodeUrl; }
    public void setQrCodeUrl(String qrCodeUrl) { this.qrCodeUrl = qrCodeUrl; }

    public String getQrCodeBase64() { return qrCodeBase64; }
    public void setQrCodeBase64(String qrCodeBase64) { this.qrCodeBase64 = qrCodeBase64; }

    public String getLotteryCriteria() { return lotteryCriteria; }
    public void setLotteryCriteria(String lotteryCriteria) { this.lotteryCriteria = lotteryCriteria; }

    public String getLotteryStatus() { return lotteryStatus; }
    public void setLotteryStatus(String lotteryStatus) { this.lotteryStatus = lotteryStatus; }

    // Helper method to check if registration is still open
    public boolean isRegistrationOpen() {
        long now = System.currentTimeMillis();
        return registrationStartTime != null && registrationEndTime != null &&
                now >= registrationStartTime.getTime() && now <= registrationEndTime.getTime();
    }

    // Helper method to check if spots are available
    public boolean hasAvailableSpots() {
        return waitlistCount < capacity;
    }
}

/**
 * Domain model representing an event with scheduling, capacity, lottery and media metadata.
 */
package ca.team.originkickoff.models;

import java.io.Serializable;
import java.util.Date;

/**
 * Serializable Event entity persisted in Firestore and used throughout the app.
 */
public class Event implements Serializable {
    /** Unique Firestore document id (not necessarily user supplied). */
    private String id;
    /** Human-readable event name. */
    private String name;
    /** Long-form description displayed in detail views. */
    private String description;
    /** Organizer user id. */
    private String organizerId;
    /** Organizer display name (denormalized for convenience). */
    private String organizerName;
    /** Date/time when the event occurs. */
    private Date eventDate;
    /** Textual location (address or place summary). */
    private String location;
    /** Latitude for geolocation validation. */
    private double locationLatitude;
    /** Longitude for geolocation validation. */
    private double locationLongitude;
    /** Optional Google Places ID. */
    private String locationPlaceId;
    /** Category tag for filtering. */
    private String category;
    /** Maximum number of accepted entrants. */
    private int capacity;
    /** Current number of users on waitlist (entrants). */
    private int waitlistCount;
    /** Number of users to be selected by lottery. */
    private int selectionSize;
    /** Flag indicating whether waitlist size is capped. */
    private boolean limitWaitlist;
    /** Maximum allowed waiting list size when limitWaitlist is true. */
    private int waitlistLimit;
    /** Registration window start timestamp. */
    private Date registrationStartTime;
    /** Registration window end timestamp. */
    private Date registrationEndTime;
    /** Remote poster image URL. */
    private String posterUrl;
    /** Base64 inline poster image (fallback/offline). */
    private String posterBase64;
    /** Whether entrant geolocation is required. */
    private boolean geolocationRequired;
    /** Monetary price (if any). */
    private double price;
    /** Creation epoch millis. */
    private long createdAt;
    /** Remote QR code image URL. */
    private String qrCodeUrl;
    /** Base64 inline QR code image. */
    private String qrCodeBase64;
    /** Criteria string influencing lottery selection. */
    private String lotteryCriteria;
    /** Lottery progression status e.g. not_conducted / conducted. */
    private String lotteryStatus;

    /** Empty constructor for Firebase serialization. */
    public Event() { }

    /**
     * Full constructor for manual instantiation.
     */
    public Event(String id, String name, String description, String organizerId, String organizerName,
                 Date eventDate, String location, String category, int capacity, int waitlistCount,
                 Date registrationStartTime, Date registrationEndTime, String posterUrl, String posterBase64,
                 boolean geolocationRequired, double price, long createdAt, String qrCodeUrl, String lotteryCriteria) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.organizerId = organizerId;
        this.organizerName = organizerName;
        this.eventDate = eventDate;
        this.location = location;
        this.category = category;
        this.capacity = capacity;
        this.waitlistCount = waitlistCount;
        this.registrationStartTime = registrationStartTime;
        this.registrationEndTime = registrationEndTime;
        this.posterUrl = posterUrl;
        this.posterBase64 = posterBase64;
        this.geolocationRequired = geolocationRequired;
        this.price = price;
        this.createdAt = createdAt;
        this.qrCodeUrl = qrCodeUrl;
        this.lotteryCriteria = lotteryCriteria;
    }

    /** @return event id */
    public String getId() { return id; }
    /** @param id new event id */
    public void setId(String id) { this.id = id; }

    /** @return name */
    public String getName() { return name; }
